items.command:
/bin/bash -lc "cat > /workspace/outputs/index.html <<'EOF'
<"'!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="theme-color" content="#f7eddb">
<title>Taco Cometa — Tacos with a little orbit</title>
<style>
:root{--ink:#27221d;--muted:#766b5e;--paper:#f7eddb;--cream:#fffaf0;--tomato:#d54e35;--orange:#f2a637;--green:#315d45;--line:#e4d6be;--purple:#49395c}
*{box-sizing:border-box} html{scroll-behavior:smooth} body{margin:0;background:var(--paper);color:var(--ink);font-family:ui-rounded,"Trebuchet MS",system-ui,-apple-system,sans-serif;line-height:1.5} a{color:inherit} .wrap{width:min(1120px,calc(100% - 40px));margin:auto}
header{padding:20px 0;border-bottom:1px solid rgba(39,34,29,.12)}.nav{display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;font-weight:900;letter-spacing:.02em;font-size:1.1rem}.brand-mark{display:grid;place-items:center;width:38px;height:38px;background:var(--tomato);color:white;border-radius:50%;font-size:22px;transform:rotate(-12deg)}nav{display:flex;gap:25px;font-weight:750;font-size:.93rem}nav a{text-decoration:none}nav a:hover{text-decoration:underline;text-decoration-thickness:2px;text-underline-offset:4px}
.hero{padding:66px 0 54px;display:grid;grid-template-columns:1.08fr .92fr;gap:40px;align-items:center}.eyebrow{font-size:.75rem;text-transform:uppercase;letter-spacing:.18em;font-weight:900;color:var(--tomato)}h1,h2,h3,p{margin-top:0}h1{font-family:Georgia,serif;font-weight:900;letter-spacing:-.055em;font-size:clamp(3.5rem,7vw,6.2rem);line-height:.92;margin:12px 0 22px;max-width:650px}h1 em{font-style:normal;color:var(--tomato)}.hero p{font-size:1.12rem;color:var(--muted);max-width:490px;margin-bottom:24px}.buttons{display:flex;gap:12px;flex-wrap:wrap}.button{display:inline-flex;align-items:center;justify-content:center;padding:12px 18px;min-height:48px;border-radius:999px;text-decoration:none;font-weight:850;border:2px solid var(--ink)}.primary{background:var(--ink);color:var(--cream)}.secondary{background:transparent}.button:hover{transform:translateY(-2px)}
.art{position:relative;min-height:340px;border-radius:48% 52% 45% 55% / 53% 45% 55% 47%;background:var(--orange);display:grid;place-items:center;overflow:hidden}.art:before,.art:after{content:"";position:absolute;border:2px solid rgba(255,250,240,.38);border-radius:50%;width:330px;height:160px;transform:rotate(-25deg)}.art:after{width:400px;height:210px;transform:rotate(18deg)}.sun{position:absolute;width:70px;height:70px;background:#f8cf68;border-radius:50%;right:14%;top:12%}.taco{font-size:clamp(120px,18vw,200px);filter:drop-shadow(0 16px 8px rgba(65,39,17,.2));z-index:1;transform:rotate(-8deg)}.orbit-label{z-index:2;position:absolute;bottom:34px;right:9%;background:var(--cream);padding:8px 14px;border-radius:999px;font-weight:900;color:var(--green);transform:rotate(5deg)}
.marquee{background:var(--green);color:#fffaf0;padding:12px 0;font-weight:850;letter-spacing:.06em;text-align:center}.marquee span{color:#f4bd4f;padding:0 8px}
section{scroll-margin-top:20px}.menu-section{padding:76px 0}.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:26px}.section-head h2,.visit h2{font:900 clamp(2.35rem,5vw,4rem)/.98 Georgia,serif;letter-spacing:-.04em;margin:8px 0 0}.section-head p{margin:0;color:var(--muted);max-width:325px}.menu-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.dish{background:var(--cream);border:1px solid var(--line);border-radius:18px;padding:20px 22px;display:grid;grid-template-columns:1fr auto;gap:4px 14px;align-content:start;min-height:148px}.dish h3{font:850 1.25rem/1.2 Georgia,serif;margin:0}.price{font-weight:900;font-size:1.06rem;white-space:nowrap;color:var(--tomato)}.dish p{grid-column:1/-1;margin:5px 0 0;color:var(--muted);font-size:.94rem}.tag{grid-column:1/-1;width:max-content;max-width:100%;display:inline-flex;align-items:center;gap:6px;margin-top:8px;border-radius:999px;padding:4px 9px;background:#e3efdc;color:#285239;font-weight:900;font-size:.74rem;letter-spacing:.035em;text-transform:uppercase}.tag:before{content:"✿"}.menu-note{font-size:.8rem;color:var(--muted);margin:16px 0 0}
.visit-band{background:var(--purple);color:#fffaf0;padding:66px 0}.visit{display:grid;grid-template-columns:1fr 1fr;gap:48px;align-items:start}.visit .eyebrow{color:#f5c25a}.visit-intro p{max-width:390px;color:#e2d9e9;margin-top:18px}.visit-card{background:#fffaf0;color:var(--ink);border-radius:22px;padding:25px 27px;box-shadow:0 10px 0 rgba(0,0,0,.08)}.visit-card h3{font:900 1.3rem Georgia,serif;margin:0 0 17px}.detail{padding:12px 0;border-top:1px solid var(--line);display:grid;grid-template-columns:105px 1fr;gap:12px}.detail dt{font-size:.75rem;text-transform:uppercase;letter-spacing:.1em;font-weight:900;color:var(--tomato)}.detail dd{margin:0;font-weight:750}.sample{display:inline-block;background:#f8e5b6;border-radius:5px;padding:1px 5px;font-size:.72rem;letter-spacing:.05em;text-transform:uppercase;color:#563919;font-weight:950;vertical-align:2px}.visit-disclaimer{font-size:.78rem;color:#e2d9e9;margin:12px 0 0}.visit-cta{margin-top:15px;display:inline-block;font-weight:850;color:var(--purple);text-underline-offset:4px}
footer{padding:20px 0;color:var(--muted);font-size:.8rem}.foot{display:flex;justify-content:space-between;gap:20px;align-items:center}.foot strong{color:var(--ink)}
@media(max-width:720px){.wrap{width:min(100% - 32px,560px)}.nav{align-items:flex-start}.brand{font-size:1rem}.brand-mark{width:34px;height:34px}nav{gap:14px;font-size:.82rem;padding-top:8px}.hero{grid-template-columns:1fr;gap:28px;padding:49px 0 38px}h1{font-size:clamp(3.65rem,15vw,5.3rem);max-width:520px}.hero p{font-size:1rem}.art{min-height:260px;width:90%;margin:auto}.taco{font-size:150px}.menu-section{padding:56px 0}.section-head{display:block}.section-head p{margin-top:12px}.menu-grid{grid-template-columns:1fr;gap:10px}.dish{padding:17px 18px;min-height:0}.visit-band{padding:52px 0}.visit{grid-template-columns:1fr;gap:27px}.visit-card{padding:20px 18px}.foot{align-items:flex-start;flex-direction:column;gap:5px}}
@media(max-width:390px){.wrap{width:calc(100% - 28px)}nav{gap:10px;font-size:.77rem}.dish{grid-template-columns:minmax(0,1fr) auto;gap:4px 8px}.dish h3{font-size:1.12rem}.detail{grid-template-columns:90px 1fr;gap:8px}.art{min-height:230px}}
</style>
</head>
<body>
<header><div class="wrap nav"><a class="brand" href="#top" aria-label="Taco Cometa home"><span class="brand-mark" aria-hidden="true">✦</span><span>TACO COMETA</span></a><nav aria-label="Main navigation"><a href="#menu">Menu</a><a href="#visit">Visit</a></nav></div></header>
<main id="top">
<div class="wrap hero"><div><div class="eyebrow">A little flavor in your orbit</div><h1>Good tacos.<br><em>Big sunshine.</em></h1><p>Fresh tortillas, bright salsas, and just the right amount of napkin-worthy. Find your next favorite in our sample menu.</p><div class="buttons"><a class="button primary" href="#menu">Explore the menu ↓</a><a class="button secondary" href="#visit">Find us (sample details)</a></div></div><div class="art" aria-hidden="true"><span class="sun"></span><span class="taco">🌮</span><span class="orbit-label">MADE FOR THE MUNCHIES</span></div></div>
<div class="marquee">FRESH TORTILLAS <span>✦</span> BIG FLAVOR <span>✦</span> GOOD VIBRATIONS</div>
<section class="menu-section" id="menu"><div class="wrap"><div class="section-head"><div><div class="eyebrow">The tasty lineup · sample menu</div><h2>Pick your orbit.</h2></div><p>Four house favorites, made for mixing and matching. Sample items and prices for this demo.</p></div><div class="menu-grid">
<article class="dish"><h3>Cometa Al Pastor</h3><span class="price">$4.50</span><p>Chile-marinated jackfruit, pineapple, onion, cilantro, salsa roja.</p><span class="tag">Vegetarian</span></article>
<article class="dish"><h3>Carne Asada</h3><span class="price">$5.00</span><p>Grilled steak, charred scallion, avocado salsa, lime.</p></article>
<article class="dish"><h3>Crispy Baja Fish</h3><span class="price">$4.75</span><p>Golden fish, crunchy cabbage, crema, smoky chile salsa.</p></article>
<article class="dish"><h3>Garden Stardust</h3><span class="price">$4.25</span><p>Roasted cauliflower, black beans, pepita crunch, salsa verde.</p><span class="tag">Vegetarian</span></article>
</div><p class="menu-note">All menu items and prices shown are sample content for a website demo.</p></div></section>
<section class="visit-band" id="visit"><div class="wrap visit"><div class="visit-intro"><div class="eyebrow">Plot a course</div><h2>Come on by.<br>(Sample info.)</h2><p>Hungry is a great direction. Here are fictional visit details included to show how a location section could look.</p><a class="visit-cta" href="#menu">Back to the menu ↑</a></div><div><div class="visit-card"><h3>Visit Taco Cometa <span class="sample">Sample details</span></h3><dl>
<div class="detail"><dt>Address</dt><dd><span class="sample">Sample</span> 123 Comet Way, Your City, CA 90000</dd></div>
<div class="detail"><dt>Hours</dt><dd><span class="sample">Sample</span> Mon–Sun · 11 am–9 pm</dd></div>
<div class="detail"><dt>Contact</dt><dd><span class="sample">Sample</span> hello@example.test · (555) 010-2040</dd></div>
</dl></div><p class="visit-disclaimer">Fictional sample address, hours, and contact details. Not real visit information.</p></div></div></section>
</main><footer><div class="wrap foot"><strong>✦ Taco Cometa</strong><span>Sample restaurant website · Demo menu and details</span></div></footer>
</body></html>
EOF
'
